-- Dedicated prototype only. Transaction-local synthetic subjects, not Auth tokens.
-- All synthetic accounts, policies, attendance and history roll back.
begin;
do $$
declare c uuid; owner_id uuid; hr_id uuid:=gen_random_uuid(); manager_id uuid:=gen_random_uuid(); staff_id uuid:=gen_random_uuid(); outside_id uuid:=gen_random_uuid();
 hr_person uuid; manager_person uuid; staff_person uuid; hr_email text; manager_email text; staff_email text; outside_email text;
 shift_id uuid; parent uuid; meal uuid; rest uuid; own_attendance uuid; own_break uuid;
 meal_rule uuid:=gen_random_uuid(); rest_rule uuid:=gen_random_uuid(); draft jsonb; change jsonb; saved jsonb;
begin
 if (select count(*) from public.companies)<>1 or to_regprocedure('public.manage_attendance_break(text,jsonb)') is null then raise exception 'Expected initialized HRIS breaks deployment.';end if;
 select id,companies.owner_id into strict c,owner_id from public.companies;
 hr_email:='qa-break-hr-'||hr_id||'@example.invalid';manager_email:='qa-break-manager-'||manager_id||'@example.invalid';staff_email:='qa-break-staff-'||staff_id||'@example.invalid';outside_email:='qa-break-outside-'||outside_id||'@example.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(hr_id,hr_email,clock_timestamp()),(manager_id,manager_email,clock_timestamp()),(staff_id,staff_email,clock_timestamp()),(outside_id,outside_email,clock_timestamp());
 perform set_config('request.headers','{"x-hris-leave-contract":"2"}',true);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 perform public.save_company_account(hr_id,hr_email,'hr_generalist',true,null,null);
 perform public.save_company_account(manager_id,manager_email,'manager',true,null,null);
 perform public.save_company_account(staff_id,staff_email,'employee',true,null,null);
 perform public.save_company_account(outside_id,outside_email,'manager',true,null,null);
 select employee_id into hr_person from public.company_members where user_id=hr_id;
 select employee_id into manager_person from public.company_members where user_id=manager_id;
 select employee_id into staff_person from public.company_members where user_id=staff_id;
 update public.employees set reports_to=manager_person,joined_on='2020-01-01' where id=staff_person;
 draft:=jsonb_build_object('id',null,'expected_revision',null,'name','Synthetic rollback break shift','days',jsonb_build_array(1,2,3,4,5,6,7),'start_minute',480,'end_minute',1020,'works_on_holidays',true,'active',true,'break_rules',jsonb_build_array(jsonb_build_object('id',meal_rule,'name','Meal','minutes',60,'paid',false,'required',true),jsonb_build_object('id',rest_rule,'name','Rest','minutes',15,'paid',true,'required',false)));
 perform set_config('request.jwt.claim.sub',hr_id::text,true);shift_id:=public.save_shift_template(draft);
 perform public.assign_shift(jsonb_build_object('employee_id',staff_person,'template_id',shift_id,'expected_template_revision',0,'expected_sequence',0,'effective_on','2026-01-01','expected_timezone',(select timezone from public.companies where id=c),'reason','Synthetic rollback break assignment'));
 parent:=public.correct_attendance(jsonb_build_object('attendance_id',null,'employee_id',staff_person,'work_date','2026-01-05','checked_in_at','2026-01-05T00:00:00Z','checked_out_at','2026-01-05T09:00:00Z','expected_revision',null,'reason','Synthetic rollback attendance'));
 change:=jsonb_build_object('attendance_id',parent,'expected_parent_revision',0,'rule_id',meal_rule,'name','Forged paid classification','paid',true,'started_at','2026-01-05T04:00:00Z','ended_at','2026-01-05T05:00:00Z','reason','Synthetic rollback meal');
 meal:=public.manage_attendance_break('record',change);
 assert (select name='Meal' and not paid and required and expected_minutes=60 and revision=0 from public.attendance_breaks where id=meal),'Server did not retain saved break classification';
 assert (select actor_id=hr_id and actor_role='hr_generalist' from public.attendance_break_events where break_id=meal),'Server break actor incorrect';
 begin perform public.manage_attendance_break('record',change||'{"expected_parent_revision":99}');raise exception 'Stale attendance revision accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.manage_attendance_break('record',change||jsonb_build_object('rule_id',rest_rule,'started_at','2026-01-05T04:30:00Z','ended_at','2026-01-05T05:15:00Z'));raise exception 'Overlapping break accepted';exception when exclusion_violation then null;end;
 begin perform public.manage_attendance_break('record',change||jsonb_build_object('rule_id',null,'started_at','2026-01-05T08:50:00Z','ended_at','2026-01-05T09:10:00Z'));raise exception 'Break outside attendance accepted';exception when check_violation then null;end;
 rest:=public.manage_attendance_break('record',change||jsonb_build_object('rule_id',rest_rule,'started_at','2026-01-05T06:00:00Z','ended_at','2026-01-05T06:15:00Z'));
 perform public.manage_attendance_break('correct',change||jsonb_build_object('id',meal,'expected_revision',0,'ended_at','2026-01-05T04:45:00Z','reason','Synthetic correction'));
 begin perform public.manage_attendance_break('correct',change||jsonb_build_object('id',meal,'expected_revision',0));raise exception 'Stale break revision accepted';exception when sqlstate 'PT409' then null;end;
 perform public.manage_attendance_break('void',change||jsonb_build_object('id',meal,'expected_revision',1,'reason','Synthetic void with retained history'));
 assert (select voided and revision=2 from public.attendance_breaks where id=meal),'Void did not retain the break';
 assert (select count(*)=3 from public.attendance_break_events where break_id=meal),'Break correction history lost';
 meal:=public.manage_attendance_break('record',change);
 assert (select sum(extract(epoch from ended_at-started_at))=3600 from public.attendance_breaks where attendance_id=parent and not paid and not voided),'Recorded unpaid totals incorrect';
 begin perform public.correct_attendance(jsonb_build_object('attendance_id',parent,'employee_id',staff_person,'work_date','2026-01-05','checked_in_at','2026-01-05T00:00:00Z','checked_out_at','2026-01-05T04:30:00Z','expected_revision',0,'reason','Synthetic invalid shortened attendance'));raise exception 'Attendance correction stranded break times';exception when check_violation then null;end;
 select to_jsonb(t) into saved from public.shift_templates t where id=shift_id;
 perform public.save_shift_template(saved||jsonb_build_object('expected_revision',0,'break_rules',jsonb_build_array(jsonb_build_object('id',meal_rule,'name','Revised paid meal','minutes',60,'paid',true,'required',true),jsonb_build_object('id',rest_rule,'name','Rest','minutes',15,'paid',true,'required',false))));
 assert (select not (planned_shift->'break_rules'->0->>'paid')::boolean from public.attendance where id=parent),'Template change rewrote attendance break policy';
 begin update public.attendance_breaks set paid=true where id=meal;raise exception 'Direct break edit allowed';exception when insufficient_privilege then null;end;
 begin delete from public.attendance_break_events where break_id=meal;raise exception 'Audit deletion allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);
 assert (select count(*)=3 from public.attendance_breaks where attendance_id=parent),'Manager cannot read direct-report breaks';
 assert not exists(select 1 from public.attendance_break_events),'Manager read HR break reasons';
 begin perform public.manage_attendance_break('correct',change||jsonb_build_object('id',rest,'expected_revision',0));raise exception 'Manager edited a team break';exception when insufficient_privilege then null;end;
 begin perform public.manage_attendance_break('start',change||jsonb_build_object('rule_id',rest_rule));raise exception 'Manager used team routine break controls';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outside_id::text,true);
 assert not exists(select 1 from public.attendance_breaks where attendance_id=parent),'Unrelated manager read break data';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 insert into public.attendance(company_id,employee_id) values(c,staff_person) returning id into own_attendance;
 own_break:=public.manage_attendance_break('start',jsonb_build_object('attendance_id',own_attendance,'expected_parent_revision',0,'rule_id',rest_rule,'paid',false,'started_at','1900-01-01T00:00:00Z'));
 assert (select paid and started_at>clock_timestamp()-interval '1 minute' from public.attendance_breaks where id=own_break),'Routine break trusted client classification/time';
 begin update public.attendance set checked_out_at=clock_timestamp() where id=own_attendance;raise exception 'Checkout allowed an open break';exception when check_violation then null;end;
 begin perform public.manage_attendance_break('record',change);raise exception 'Employee used HR manual break control';exception when insufficient_privilege then null;end;
 perform public.manage_attendance_break('end',jsonb_build_object('attendance_id',own_attendance,'expected_parent_revision',0,'id',own_break,'expected_revision',0));
 update public.attendance set checked_out_at=clock_timestamp() where id=own_attendance;
 assert (select checked_out_at is not null from public.attendance where id=own_attendance),'Checkout failed after the break ended';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.save_company_account(hr_id,hr_email,'hr_generalist',false,null,null);
 perform set_config('request.jwt.claim.sub',hr_id::text,true);
 assert not exists(select 1 from public.attendance_breaks),'Disabled HR read breaks';
 begin perform public.manage_attendance_break('record',change);raise exception 'Disabled HR recorded break';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';
 begin perform * from public.attendance_breaks;raise exception 'Anonymous break read allowed';exception when insufficient_privilege then null;end;
 begin perform public.manage_attendance_break('record',change);raise exception 'Anonymous break write allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 assert not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef),'Public definer exposed';
 assert (select count(*)=2 from pg_class t join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname in ('attendance_breaks','attendance_break_events') and t.relrowsecurity),'Break RLS missing';
end;
$$;
rollback;
